const params      = $('Parâmetros').first().json;
const filterStatus = params.filter_status;
const reportType   = params.report_type;  // concluidas | pendentes | completo | por_categoria
const dateStart    = params.date_start;
const dateEnd      = params.date_end;

let tasks = $input.all().map(i => i.json).filter(t => t.status !== 'archived');

// Filtra por status se necessário
if (filterStatus && filterStatus !== 'all') {
  tasks = tasks.filter(t => t.status === filterStatus);
}

// Helpers
const total = tasks.length;
const open  = tasks.filter(t => t.status === 'open').length;
const done  = tasks.filter(t => t.status === 'done').length;

const fmtHora = t => t.scheduled_time ? t.scheduled_time.substring(0,5) : null;
const fmtTask = t => {
  const icon   = t.status === 'done' ? '✅' : '⏳';
  const hora   = fmtHora(t) ? ` (${fmtHora(t)})` : '';
  const cat    = t.category ? ` — ${t.category}` : '';
  return `${icon} [ID:${t.id}] ${t.title}${hora}${cat}`;
};

let list_formatted = '';

if (reportType === 'concluidas') {
  const concluidas = tasks.filter(t => t.status === 'done');
  list_formatted = concluidas.length === 0
    ? 'Nenhuma tarefa concluída no período.'
    : concluidas.map(fmtTask).join('\n');

} else if (reportType === 'pendentes') {
  const pendentes = tasks.filter(t => t.status === 'open');
  list_formatted = pendentes.length === 0
    ? 'Nenhuma tarefa pendente no período. 🎉'
    : pendentes.map(fmtTask).join('\n');

} else if (reportType === 'por_categoria') {
  const byCat = {};
  tasks.forEach(t => {
    const cat = t.category || 'Sem categoria';
    if (!byCat[cat]) byCat[cat] = [];
    byCat[cat].push(t);
  });
  if (Object.keys(byCat).length === 0) {
    list_formatted = 'Nenhuma tarefa encontrada.';
  } else {
    list_formatted = Object.entries(byCat)
      .map(([cat, ts]) => `📂 *${cat}*\n` + ts.map(fmtTask).join('\n'))
      .join('\n\n');
  }

} else {
  // completo (padrão)
  list_formatted = tasks.length === 0
    ? 'Nenhuma tarefa encontrada.'
    : tasks.map(fmtTask).join('\n');
}

return [{ json: {
  date_start:     dateStart,
  date_end:       dateEnd,
  report_type:    reportType,
  total,
  open,
  done,
  tasks,
  list_formatted
}}];
